sys_script_include.script:
var TaskActionHandler = Class.create();
TaskActionHandler.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    completeTask: function() {
        var taskID = this.getParameter('sysparam_task_id');
        var gr = new GlideRecord('x_1790233_event_ma_event_task');
        gr.addQuery('number', taskID);
        if (gr.next()) {
            gr.setValue('status', 'completed');
            gr.update();
            return 'Task Marked Completed';
        } else {
            return 'Task not Found';
        }
    },
    cancelTask: function() {
        var taskId = this.getParameter('sysparm_task_id');
        var gr = new GlideRecord('x_1790233_event_ma_event_task');
        if (gr.get(taskId)) {
            gr.setValue('status', 'Cancelled');
            gr.update();
            return 'Task cancelled';
        }
        return 'Task not found';

    },
    type: 'TaskActionHandler'
});
